<template><ContentWrap><el-tabs v-model="tab"><el-tab-pane label="Provider" name="provider"><el-button type="primary" @click="editProvider()">新增 Provider</el-button><el-table :data="providers"><el-table-column prop="name" label="名称"/><el-table-column prop="providerType" label="类型"/><el-table-column label="凭证"><template #default="{row}">{{row.apiKeyConfigured?'已配置':'未配置'}}</template></el-table-column><el-table-column prop="status" label="状态"/></el-table></el-tab-pane><el-tab-pane label="模型" name="model"><el-button type="primary" @click="modelOpen=true">新增模型</el-button><el-table :data="models"><el-table-column prop="name" label="名称"/><el-table-column prop="modelCode" label="模型"/><el-table-column prop="modelType" label="类型"/><el-table-column prop="status" label="状态"/></el-table></el-tab-pane></el-tabs><ProviderForm v-model="providerOpen" :value="editing" @saved="load"/><el-dialog v-model="modelOpen" title="模型"><el-form :model="modelForm"><el-form-item label="类型"><el-select v-model="modelForm.modelType"><el-option v-for="x in modelTypes" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="模型编码"><el-input v-model="modelForm.modelCode"/></el-form-item></el-form></el-dialog></ContentWrap></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {AiModelApi,type ProviderVO} from '@/api/ai/model';import ProviderForm from './components/ProviderForm.vue';const tab=ref('provider'),providers=ref<ProviderVO[]>([]),models=ref<any[]>([]),providerOpen=ref(false),modelOpen=ref(false),editing=ref<ProviderVO>(),modelForm=ref<any>({modelType:'CHAT'});const modelTypes=['CHAT','REALTIME_S2S','ASR','TTS','EMBEDDING'];async function load(){providers.value=await AiModelApi.listProviders();models.value=await AiModelApi.listModels()}function editProvider(v?:ProviderVO){editing.value=v;providerOpen.value=true}onMounted(load)</script>